<?php
 namespace QQWorld\Directory\Model; use QQWorld\Framework\App\Config\ScopeConfigInterface; use QQWorld\Store\Model\ScopeInterface; use QQWorld\Store\Model\StoreManagerInterface; class AllowedCountries { const ALLOWED_COUNTRIES_PATH = 'general/country/allow'; private $scopeConfig; private $storeManager; public function __construct( ScopeConfigInterface $scopeConfig, StoreManagerInterface $storeManager ) { $this->scopeConfig = $scopeConfig; $this->storeManager = $storeManager; } public function getAllowedCountries( $scope = ScopeInterface::SCOPE_WEBSITE, $scopeCode = null ) { if (empty($scopeCode)) { $scopeCode = $this->getDefaultScopeCode($scope); } switch ($scope) { case ScopeInterface::SCOPE_WEBSITES: case ScopeInterface::SCOPE_STORES: $allowedCountries = []; foreach ($scopeCode as $singleFilter) { $allowedCountries = array_merge( $allowedCountries, $this->getCountriesFromConfig($this->getSingleScope($scope), $singleFilter) ); } break; default: $allowedCountries = $this->getCountriesFromConfig($scope, $scopeCode); } return $this->makeCountriesUnique($allowedCountries); } private function getDefaultScopeCode($scope) { switch ($scope) { case ScopeInterface::SCOPE_WEBSITE: return $this->storeManager->getWebsite()->getId(); case ScopeInterface::SCOPE_STORE: return $this->storeManager->getStore()->getId(); case ScopeInterface::SCOPE_GROUP: return $this->storeManager->getGroup()->getId(); case ScopeInterface::SCOPE_WEBSITES: return [$this->storeManager->getWebsite()->getId()]; case ScopeInterface::SCOPE_STORES: return [$this->storeManager->getStore()->getId()]; default: throw new \InvalidArgumentException("Invalid scope is specified"); } } public function makeCountriesUnique(array $allowedCountries) { return array_combine($allowedCountries, $allowedCountries); } public function getCountriesFromConfig($scope, $scopeCode) { return explode( ',', (string) $this->scopeConfig->getValue( self::ALLOWED_COUNTRIES_PATH, $scope, $scopeCode ) ); } private function getSingleScope($scope) { if ($scope == ScopeInterface::SCOPE_WEBSITES) { return ScopeInterface::SCOPE_WEBSITE; } if ($scope == ScopeInterface::SCOPE_STORES) { return ScopeInterface::SCOPE_STORE; } return $scope; } } 